package com.rationportal.model; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="onorc_portability") public class OnorcPortability { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="reference_number",unique=true,nullable=false) private String referenceNumber; @Column(name="ration_card_number",nullable=false) private String rationCardNumber; @Column(name="home_state",nullable=false) private String homeState; @Column(name="home_district",nullable=false) private String homeDistrict; @Column(name="destination_state",nullable=false) private String destinationState; @Column(name="destination_district",nullable=false) private String destinationDistrict; @Column(name="fps_name") private String fpsName; @Column(name="fps_code") private String fpsCode; @Column(nullable=false) private String status; @Column(name="requested_by",nullable=false) private String requestedBy; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist protected void onCreate(){if(createdAt==null)createdAt=LocalDateTime.now();} public Long getId(){return id;} public String getReferenceNumber(){return referenceNumber;} public void setReferenceNumber(String v){referenceNumber=v;} public String getRationCardNumber(){return rationCardNumber;} public void setRationCardNumber(String v){rationCardNumber=v;} public String getHomeState(){return homeState;} public void setHomeState(String v){homeState=v;} public String getHomeDistrict(){return homeDistrict;} public void setHomeDistrict(String v){homeDistrict=v;} public String getDestinationState(){return destinationState;} public void setDestinationState(String v){destinationState=v;} public String getDestinationDistrict(){return destinationDistrict;} public void setDestinationDistrict(String v){destinationDistrict=v;} public String getFpsName(){return fpsName;} public void setFpsName(String v){fpsName=v;} public String getFpsCode(){return fpsCode;} public void setFpsCode(String v){fpsCode=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getRequestedBy(){return requestedBy;} public void setRequestedBy(String v){requestedBy=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
